    function handleMenuEvent(menuElement) {
        $(".sec_menu_mob").hide();
        $(".menu-r").show();

        if ($(menuElement).hasClass("link")) {
            return;
        }

        var index = $(menuElement).attr("data-count");
        if (window.innerWidth > 1199) {
            $(".row.mx-0.menuBlock").attr("id", "menuBlock" + index);
        } else {
            $(".row.mx-0.menuBlock").attr("id", "");
        }

        $(".main_menu").removeClass("active");
        $(".main_menu").eq($('.main_menu2').index(menuElement)).addClass('active');
        $(".sec_menu ul.cart").hide();
        $(".sec_menu ul.cart").eq($('.main_menu2').index(menuElement)).show();
        $('li.cartTitle').removeClass("active");
        $(".sec_menu_mob ul.cart").hide();
        $(".sec_menu_mob ul.cart").eq($('.main_menu2').index(menuElement)).show();
        $(".sec_menu ul.cart ul").hide();
        $('.cart > li > a').removeClass("active");
        $('body').addClass('nav-expanded');

        prev = index; // 先声明 prev 变量并赋值
    }

    $('#nav-close').on('click', function (e) {
        e.preventDefault();
        $('body').removeClass('nav-expanded');
    });

