//紀錄選單Session設定
function ClickMenu(firstMenu, secondMenu) {
    var thisPage = location.href.split('#')[0]
    sessionStorage.setItem("lastPage", thisPage);
    sessionStorage.setItem("firstMenu", firstMenu);
    sessionStorage.setItem("secondMenu", secondMenu);
}

$(document).ready(function () {
    //偵測到上一頁事件要記錄
    //window.addEventListener("popstate", function (e) {
    //    sessionStorage.setItem("isPopstate", "1");
    //}, false);

    //重讀頁面判斷是否要展開選單
    var isPopstate = sessionStorage.getItem("isPopstate");
    sessionStorage.setItem("isPopstate", "");
    var lastPage = sessionStorage.getItem("lastPage");
    var thisPage = location.href.split('#')[0]
    if (isPopstate == "1" || thisPage == lastPage) {
        //取消展開動畫
        $("nav").addClass("noAnimation");

        setTimeout(function () {
            var firstMenu = sessionStorage.getItem("firstMenu");
            var secondMenu = sessionStorage.getItem("secondMenu");

            if (firstMenu == '') {
                //展開選單
                $("body").toggleClass("nav-expanded");
            }
            else {
                if (window.innerWidth > 1199) {
                    //滿版選單(電腦版)
                    if (secondMenu === '') {
                        //展開選單
                        $("body").toggleClass("nav-expanded");
                        //點選第一層
                        $('.main_menu ').each(function () { $(this).removeClass('active') });
                        $('.main_menuTitle[data-count="' + firstMenu + '"]').click();
                    }
                    else {
                        //展開選單
                        $("body").toggleClass("nav-expanded");
                        //點選第一層
                        $('.main_menu ').each(function () { $(this).removeClass('active') });
                        $('.main_menuTitle[data-count="' + firstMenu + '"]').click();
                        //點選第二層
                        $('.cart').eq(parseInt(firstMenu, 10)).find('li.cartTitle').eq(parseInt(secondMenu, 10) - 1).click();
                    }
                }
                else {
                    //小螢幕選單.點選第一層
                    $("a.nav-expander").click();
                    $('.main_menu ').each(function () { $(this).removeClass('active') });
                    $('.main_menuTitle[data-count="' + firstMenu + '"]').click();
                }
            }
        }, 500);
    }
});

//打開選單功能
function OpenMenu(firstMenu, secondMenu) {
    //恢復展開動畫
    $("nav").removeClass("noAnimation");

    if (firstMenu == '') {
        //展開選單
        $("body").toggleClass("nav-expanded");
    }
    else {
        if (window.innerWidth > 1199) {
            //滿版選單(電腦版)
            if (secondMenu === '') {
                //展開選單
                $("body").toggleClass("nav-expanded");
                //點選第一層
                $('.main_menu ').each(function () { $(this).removeClass('active') });
                $('.main_menuTitle[data-count="' + firstMenu + '"]').click();
            }
            else {
                //展開選單
                $("body").toggleClass("nav-expanded");
                //點選第一層
                $('.main_menu ').each(function () { $(this).removeClass('active') });
                $('.main_menuTitle[data-count="' + firstMenu + '"]').click();
                //點選第二層
                $('.cart').eq(parseInt(firstMenu, 10)).find('li.cartTitle').eq(parseInt(secondMenu, 10) - 1).click();
            }
        }
        else {
            //小螢幕選單.點選第一層
            $("a.nav-expander").click();
            $('.main_menu ').each(function () { $(this).removeClass('active') });
            $('.main_menuTitle[data-count="' + firstMenu + '"]').click();
        }
    }
}

$(document).ready(function () {
    const UrlParams = new URL(window.location.href);
    const objValue = UrlParams.searchParams.get('redirect');
    if (objValue == "esg") {
        OpenMenu('01', '');
    }
});
